WITH eligible AS (SELECT s.* FROM sessions s WHERE EXISTS (SELECT 1 FROM web_events c WHERE c.session_id = s.id AND c.page IS NOT NULL)) SELECT s.id, s.customer_id, s.device, s.browser, s.started_at, s.country, CASE WHEN device RLIKE '^(desktop|tablet)$' THEN 'CORE' ELSE 'EXTENDED' END AS device_zone, (SELECT MIN(x.shipping_fee) FROM orders x WHERE x.customer_id = s.customer_id) AS min_order_shipping_fee FROM eligible s ORDER BY browser NULLS FIRST;
